-- Generated by tools/catalog-to-sql.mjs from content/categories.json. Do not edit by hand.
-- Upserts the 68 built-in categories by slug. Safe to run more than once.
-- Never touches daily_puzzles: published puzzles keep the snapshot they were frozen with.
begin;

on conflict (slug) do update
  set name = excluded.name, title = excluded.title, grp = excluded.grp, fam = excluded.fam, sub = excluded.sub, kind = excluded.kind, season = excluded.season,
      opts = excluded.opts, clues = excluded.clues, active = true, updated_at = now()
  where public.catalog.source = 'builtin';

-- A built-in category removed from the file is retired, not deleted (votes and history stay).
update public.catalog set active = false, updated_at = now()
 where source = 'builtin' and active
   and slug not in ('nfl-quarterback', 'nfl-running-back', 'nfl-wide-receiver', 'nfl-tight-end', 'nfl-offensive-lineman', 'nfl-defensive-lineman', 'nfl-linebacker', 'nfl-defensive-back', 'nba-player', 'soccer-player', 'tennis-player', 'golfer', 'boxer', 'olympic-athlete', 'movie-villain', 'action-movie-star', 'comedy-actor', 'movie-franchise', 'best-picture-winner', 'disney-animated-movie', 'plot-twist-movie', 'romantic-movie', 'horror-movie', 'christmas-movie', 'sitcom', 'tv-drama', 'cartoon-series', 'rapper', 'rock-band', 'guitarist', 'pizza-topping', 'burger-chain', 'fast-food-fries', 'steak-cut', 'bbq-food', 'pasta-dish', 'breakfast-food', 'breakfast-cereal', 'thanksgiving-side', 'candy-bar', 'cookie', 'ice-cream-flavor', 'potato-chip', 'soft-drink', 'super-bowl-snack', 'video-game', 'gaming-console', 'board-game', 'superhero', 'superpower', 'fictional-character', 'car-brand', 'sneaker-brand', 'pop-singer', 'grunge-band', 'drummer', 'nfl-team', 'nfl-player', 'nba-point-guard', 'nba-shooting-guard', 'nba-center', 'nba-small-forward', 'nba-power-forward', 'mlb-player', 'mlb-outfielder', 'mlb-infielder', 'mlb-catcher', 'mlb-pitcher');

commit;
